// A delayed execution which rewards separating one enemy from the crowd.
const ISOLATION_BELL_SIGNATURE=['孤立の鐘',24,7,'敵1体に1.2秒の印。発動時と決着時の両方で、その敵から180以内に射線が通る別の生存敵がいなければ500%の一撃。途中に敵が近づいても決着前に引き離せば成功。密集したまま発動すると不発。孤立判定は範囲補正・属性で変わらない。対象が自分から500を超える・壁に隠れる・倒れる・自分の死亡や地域移動で解除。再発動で置き換える。','M16 34V22Q16 8 28 8Q40 8 40 22V34L45 40H11ZM24 45H32M5 14L10 18M46 14L51 10'];
SIGNATURE_SKILLS.push(ISOLATION_BELL_SIGNATURE);Object.assign(GEM.crafted_6_0,{name:ISOLATION_BELL_SIGNATURE[0],cost:24,cool:7,desc:ISOLATION_BELL_SIGNATURE[3],ability:null,signature:104,tags:['spell']});
SIGNATURE_AUDIO.push(['isolationbell',410,.4]);SKILL_AUDIO_FAMILIES.heavy.add('isolationbell');
function isolationBellAlone(target){return !enemies.some(e=>e!==target&&e.hp>0&&dist(target,e)<=180&&lineClear(target,e));}
function isolationBellValid(s){return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&s.target?.hp>0&&enemies.includes(s.target)&&dist(p,s.target)<=500&&lineClear(p,s.target);}
const isolationBellCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{const result=isolationBellCastBase(build,...args);if(GEM[build.type]?.signature!==104)return result;const s=signatureSpells.at(-1);if(s?.mode!==104)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==104||v===s);Object.assign(s,{owner:p,world:dungeon,finished:false});if(!isolationBellValid(s)||!isolationBellAlone(s.target)){s.finished=true;signatureSpells=signatureSpells.filter(v=>v!==s);say('周囲180に別の敵がいない相手を狙ってください');}return result;};
const isolationBellStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==104)return isolationBellStepBase(s,dt);if(!isolationBellValid(s)){s.finished=true;return false;}if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time+1e-8<1.2)return true;s.finished=true;if(!isolationBellAlone(s.target))return false;const e=s.target;spellHit(e,s.damage*5,s.build);burst(e.x,e.y,60,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(104,true,e.x,e.y);return false;};
const isolationBellPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{isolationBellPaintBase();for(const s of signatureSpells){if(s.mode!==104||!isolationBellValid(s)||!visibleAt(s.target.x,s.target.y))continue;const e=s.target,color=isolationBellAlone(e)?ELEMENTS[s.build.elements[0]].color:'#8c8584';groundRing(e.x,e.y,180,color,1);groundRing(e.x,e.y,40*Math.max(0,1-s.time/1.2),'#ffe4aa',3);}};
const isolationBellStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===104?{label:(isolationBellAlone(s.target)?'孤立':'敵が近い')+' · '+Math.max(0,1.2-s.time).toFixed(1)+'秒',value:Math.min(1,s.time/1.2),waiting:true}:isolationBellStatusBase(s);
